#pragma once
static void brandingTests(Window &w,const QString &output,std::function<void(QString,bool)> check){
 auto reset=[&](bool english){w.model=Model::example();w.history.clear();w.selectionIds.clear();w.selection.clear();w.uml=false;w.en=english;w.mode=1;w.applyTheme();w.buildMenus();w.refresh();w.fit();w.activateWindow();qApp->processEvents();};
 auto key=[&](QWidget *widget,int code){QKeyEvent down(QEvent::KeyPress,code,Qt::NoModifier),up(QEvent::KeyRelease,code,Qt::NoModifier);QApplication::sendEvent(widget,&down);QApplication::sendEvent(widget,&up);};
 reset(false);{Window defaults(true);check("Italian is the default interface language",!defaults.en);}w.applyTheme();w.activateWindow();w.view->setFocus();qApp->processEvents();
 check("Application and executable branding",w.windowTitle().contains("0.9.7")&&w.windowTitle().contains("Database Schema Studio")&&QCoreApplication::applicationName()=="DbSchemaStudio"&&QFileInfo(QCoreApplication::applicationFilePath()).fileName()=="DbSchemaStudio.exe");
 w.selectOnly("ordine");w.view->setFocus();qApp->processEvents();int count=w.model.attributes("ordine").size();key(w.view,Qt::Key_Insert);check("Insert in diagram adds an attribute",w.model.attributes("ordine").size()==count+1&&w.model.get(w.selection)->kind=="attribute");key(w.view,Qt::Key_Insert);check("Repeated Insert keeps attribute owner",w.model.attributes("ordine").size()==count+2);
 w.history.undo();w.history.undo();check("Insert edits support undo",w.model.json()==Model::example().json());
 w.selectOnly("riga");w.tree->setFocus();qApp->processEvents();key(w.tree,Qt::Key_Insert);check("Insert works from outline",w.model.attributes("riga").size()==3);w.history.undo();
 w.selectionIds.clear();w.selection.clear();w.applySelection();w.view->setFocus();key(w.view,Qt::Key_Insert);check("Insert without selection creates an entity",w.model.objects.size()==8&&w.model.get(w.selection)->kind=="entity");w.history.undo();
 w.selectOnly("contiene");w.view->setFocus();auto before=w.model.json();key(w.view,Qt::Key_Insert);qApp->processEvents();auto focused=w.formWidget->findChild<QLineEdit*>();check("Insert on a relationship opens properties",w.model.json()==before&&focused&&focused->selectedText()=="Contiene"&&w.properties->isVisible());
 auto field=w.formWidget->findChild<QLineEdit*>();if(field){field->setFocus();key(field,Qt::Key_Insert);}check("Insert in property text never creates objects",w.model.json()==before);
 check("Copyright text and exact InfoTechLab target",w.credit->text().contains("© 2026 Prof. ing. Raffaele Mele")&&w.credit->text().contains("https://infotechlab.altervista.org"));
 QUrl opened;auto originalOpen=w.openExternal;w.openExternal=[&](const QUrl &url){opened=url;return true;};QMetaObject::invokeMethod(w.credit,"linkActivated",Qt::DirectConnection,Q_ARG(QString,w.profileUrl()));check("Copyright click dispatches to InfoTechLab",opened==QUrl("https://infotechlab.altervista.org"));w.openExternal=originalOpen;
 check("Italian flag is a scalable rendered image",!w.flag->pixmap(Qt::ReturnByValue).isNull()&&w.flag->accessibleName()=="Bandiera italiana");
 check("Default Qt buttons translated to Italian",QCoreApplication::translate("QPlatformTheme","Cancel")=="Annulla");
 {QFileDialog dialog(&w);dialog.setOption(QFileDialog::DontUseNativeDialog);check("File picker labels follow Italian",dialog.labelText(QFileDialog::FileName).contains("nome",Qt::CaseInsensitive));}
 check("Parser errors localized to Italian",localizedError("Attribute owner missing",false).contains("Entità")&&!localizedError("Invalid JSON / JSON non valido",false).contains("Invalid"));
 w.selectOnly("ordine");check("Object tooltip explains modeling and shortcuts",w.nodes["ordine"]->toolTip().contains("concettuale")&&w.nodes["ordine"]->toolTip().contains("Ins"));
 bool informative=false;for(auto action:w.findChildren<QAction*>())if(action->text()=="Attributo")informative|=action->toolTip().contains("Nessun tipo SQL")&&action->toolTip().contains("Ins");check("Toolbar tooltip explains attribute behavior",informative);
 {auto point=w.view->mapFromScene(w.nodes["ordine"]->sceneBoundingRect().center());QHelpEvent event(QEvent::ToolTip,point,w.view->viewport()->mapToGlobal(point));QApplication::sendEvent(w.view->viewport(),&event);qApp->processEvents();check("Diagram hover displays explanatory help",QToolTip::text().contains("Entità concettuale")&&QToolTip::text().contains("Ins"));for(auto widget:qApp->topLevelWidgets())if(widget->inherits("QTipLabel"))widget->grab().save(output+"/tooltip-italiano.png");QToolTip::hideText();}
 qApp->processEvents();w.grab().save(output+"/interface-italiano.png");
 {QScopedPointer<QDialog> dialog(w.aboutDialog());dialog->show();qApp->processEvents();auto legal=dialog->findChild<QLabel*>("aboutCopyright");check("About attribution matches requested wording",legal&&legal->text()=="software didattico - © 2026 Prof. ing. Raffaele Mele");dialog->grab().save(output+"/about-italiano.png");dialog->close();}
 w.selectOnly("ordine");w.addAttribute();auto unchanged=w.model.json();w.en=true;w.buildMenus();w.refresh();qApp->processEvents();check("Language switch preserves the user's model",w.model.json()==unchanged);check("Existing undo descriptions switch language",w.history.undoText()=="Create attribute");
 check("Qt standard buttons switch to English",QCoreApplication::translate("QPlatformTheme","Cancel")=="Cancel");
 {QFileDialog dialog(&w);dialog.setOption(QFileDialog::DontUseNativeDialog);check("File picker labels follow English",dialog.labelText(QFileDialog::FileName).contains("File",Qt::CaseInsensitive));}
 check("Parser errors localized to English",localizedError("Invalid JSON / JSON non valido",true)=="Invalid JSON");
 w.selectOnly("ordine");check("Object help switches to English",w.nodes["ordine"]->toolTip().contains("Conceptual entity")&&!w.nodes["ordine"]->toolTip().contains("Entità concettuale"));
 auto about=w.findChild<QAction*>("aboutAction");check("English About command exists once",about&&about->text().startsWith("About")&&w.findChildren<QAction*>("aboutAction").size()==1);
 w.uml=true;w.refresh();check("UML discriminator label follows English",w.nodes["numriga"]->label.contains("{local ID}"));w.en=false;w.buildMenus();w.refresh();check("UML discriminator label follows Italian",w.nodes["numriga"]->label.contains("{ID locale}"));
 reset(true);w.selectOnly("contiene");qApp->processEvents();w.grab().save(output+"/interface-english.png");{QScopedPointer<QDialog> dialog(w.aboutDialog());dialog->show();qApp->processEvents();check("About heading switches to English",dialog->windowTitle().startsWith("About"));dialog->grab().save(output+"/about-english.png");dialog->close();}
 reset(false);w.selectOnly("ordine");w.view->setFocus();qApp->processEvents();
}
